def _create_buvis_options(settings_class: type[T]) -> Callable[[F], F]:
    """Build a decorator that injects settings into the Click context."""

    def decorator(f: F) -> F:
        @click.version_option(
            version=pkg_version("buvis-gems"),
            prog_name="buvis-gems",
        )
        @click.option(
            "--feedback",
            is_flag=True,
            is_eager=True,
            expose_value=False,
            callback=_feedback_callback,
            help="Open feedback form in browser.",
        )
        @click.option(
            "--update",
            is_flag=True,
            is_eager=True,
            expose_value=False,
            callback=_update_callback,
            help="Force-check for updates and upgrade if newer version is available.",
        )
        @click.option(
            "--config",
            type=click.Path(exists=True, dir_okay=False, resolve_path=True),
            help="YAML config file path.",
        )
        @click.option(
            "--config-create",
            type=click.Path(dir_okay=False, resolve_path=True),
            help="Generate YAML config template to FILE.",
        )
        @click.option(
            "--config-dir",
            type=click.Path(exists=True, file_okay=False, resolve_path=True),
            help="Configuration directory.",
        )
        @click.option(
            "--log-level",
            type=click.Choice(["DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"], case_sensitive=False),
            default=None,
            help="Logging level.",
        )
        @click.option(
            "--debug/--no-debug",
            default=None,
            help="Enable debug mode.",
        )
        @click.pass_context
        @functools.wraps(f)
        def wrapper(  # noqa: PLR0913, PLR0917  # receives all buvis_options Click params
            ctx: click.Context,
            debug: bool | None,
            log_level: str | None,
            config_dir: str | None,
            config_create: str | None,
            config: str | None,
            *args: Any,
            **kwargs: Any,
        ) -> Any:
            if config_create:
                from .config_writer import ConfigWriter

                output = Path(config_create)
                cmd_name = ctx.info_name or "unknown"
                try:
                    ConfigWriter.write(settings_class, output, cmd_name)
                    click.echo(f"Config written to {output}")
                except FileExistsError as e:
                    raise click.ClickException(str(e)) from e
                ctx.exit(0)

            cli_overrides = {k: v for k, v in {"debug": debug, "log_level": log_level}.items() if v is not None}

            resolver = ConfigResolver()
            settings = resolver.resolve(
                settings_class,  # type: ignore[type-var]
                config_dir=config_dir,
                config_path=Path(config) if config else None,
                cli_overrides=cli_overrides,
            )

            ctx.ensure_object(dict)
            ctx.obj[settings_class] = settings
            if settings_class is GlobalSettings:
                ctx.obj["settings"] = settings

            # Publish the raw --config / --config-dir selection so a tool's own
            # config loader can honour the same source the settings were resolved
            # from. Additive: existing readers key off the settings entries above
            # and are untouched. Both are None when the flag was not given.
            ctx.obj["config_dir"] = config_dir
            ctx.obj["config_path"] = config

            return ctx.invoke(f, *args, **kwargs)

        _buvis_callbacks.add(wrapper)
        if issubclass(settings_class, GlobalSettings):
            _buvis_callback_settings[wrapper] = settings_class
        return wrapper  # type: ignore[return-value]

    return decorator


